import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Relative predicted-tardiness: projected finish time of this job on each machine divided by the mean projected finish time, using an estimate of remaining work per machine from past jobs."""
    m = len(loads)
    if past_jobs.size > 0:
        mean_past = float(np.mean(past_jobs))
    else:
        mean_past = job
    # expected remaining work per machine from future jobs
    remaining_work = jobs_left * mean_past
    per_machine_future = remaining_work / m
    proj = loads + job + per_machine_future
    ref = float(np.mean(proj))
    if ref <= 1e-12:
        return np.zeros(m)
    return (proj - ref) / (abs(ref) + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative relative distance of each machine's post-placement load from the current maximum load."""
    mx = loads.max()
    return -np.abs(loads + job - mx) / (mx + job + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Relative predicted-tardiness where the future-work estimate per machine is the expected max-share: each machine's projected finish including a future load that grows with a concentration term (variance of past sizes), measured against the mean projected finish."""
    m = len(loads)
    if past_jobs.size > 0:
        mean_past = float(np.mean(past_jobs))
        std_past = float(np.std(past_jobs))
    else:
        mean_past = job
        std_past = 0.0
    # expected remaining work per machine, plus a concentration correction:
    # large jobs (high std) tend to land unevenly, so weight remaining pressure higher
    remaining_work = jobs_left * mean_past
    conc = remaining_work * (std_past / (mean_past + 1e-9)) * 0.5
    per_machine_future = (remaining_work + conc) / m
    proj = loads + job + per_machine_future
    ref = float(np.mean(proj))
    if abs(ref) <= 1e-12:
        return np.zeros(m)
    return (proj - ref) / (abs(ref) + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """For large arriving jobs, cost of placing on a machine proportional to how much of that machine's load is 'big-job' load, estimated as its load minus the count of small past jobs it could have absorbed; small jobs get zero."""
    m = len(loads)
    if past_jobs.size == 0:
        return np.zeros(m)
    big = float(np.max(past_jobs))
    # gate: only act when the arriving job is comparable to the largest seen
    gate = float(np.clip((job / (big + 1e-9) - 0.5) * 2.0, 0.0, 1.0))
    if gate <= 0.0:
        return np.zeros(m)
    # small jobs are those well below the big threshold; they tend to fill machines cheaply
    small_mask = past_jobs < 0.5 * big
    small_work = float(np.sum(past_jobs[small_mask]))
    # expected small work already spread across machines (uniformly)
    small_per_machine = small_work / m
    # portion of each machine's load NOT explainable by small jobs = big-job concentration
    big_share = loads - small_per_machine
    scale = abs(big) + 1e-9
    return -gate * np.tanh(big_share / scale)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Capped tail-attraction charge alone: how much future tail work each machine will attract (cap*att), normalised to [-1, 1]."""
    m = len(loads)
    if past_jobs.size >= 5:
        q90 = float(np.percentile(past_jobs, 90))
    elif past_jobs.size > 0:
        q90 = float(np.max(past_jobs))
    else:
        q90 = float(job)
    cap = min(jobs_left * q90 / m, q90)
    lo = float(np.min(loads))
    att = np.exp(-(loads - lo) / (q90 + 1e-9))
    charge = cap * att
    return (charge - np.mean(charge)) / (np.max(charge) - np.min(charge) + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """For large arriving jobs, penalise machines by how much their load already exceeds the smallest load (relative), gated on job size vs the largest observed job, normalised to [-1,0]."""
    m = len(loads)
    if past_jobs.size > 0:
        big = float(np.max(past_jobs))
    else:
        big = float(job)
    big = max(big, 1e-9)
    large_job = min(1.0, float(job) / (0.8 * big))
    # how far each machine sits above the lightest machine, relative to the largest job seen
    excess = (loads - float(np.min(loads))) / big
    return -large_job * np.tanh(excess)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Headroom of each machine in units of expected big-job count, tanh-squashed with a mild over-depth penalty."""
    m = len(loads)
    if past_jobs.size < 5:
        return np.zeros(m)
    mx = float(np.max(past_jobs))
    big = float(np.quantile(past_jobs, 0.90))
    if big <= 1e-9:
        return np.zeros(m)
    freq = float(np.mean(past_jobs >= 0.5 * mx))
    need = float(jobs_left) * freq / m
    target = (float(np.sum(loads)) + job + float(jobs_left) * float(np.mean(past_jobs))) / m
    post = loads + job
    depth = (target - post) / (big + 1e-9)
    return np.tanh(depth - need) - 0.3 * np.tanh(depth - need - 3.0)

