import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    m = len(loads)
    mean_past = float(np.mean(past_jobs)) if past_jobs.size else job
    fut = float(jobs_left) * mean_past / m
    post = loads + job
    proj = post + fut
    if m > 1:
        ceiling = float(np.partition(proj, m - 2)[m - 2])
    else:
        ceiling = float(np.max(proj))
    excess = np.maximum(0.0, proj - ceiling) / (ceiling + 1e-9)
    return -excess - 0.05 * (post / (float(np.max(post)) + 1e-9))

