import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative inferred count of big (top-decile) jobs on each machine after placing the job, using a soft (smooth) count instead of a floor, plus a small post-load tie-break."""
    m = len(loads)
    if past_jobs.size < 10:
        return np.zeros(m)
    q = float(np.quantile(past_jobs, 0.90))
    bigs = past_jobs[past_jobs >= q]
    big = float(np.mean(bigs)) if bigs.size else q
    if big <= 1e-9:
        return np.zeros(m)
    post = loads + job
    # smooth inferred big-job count: post/big, capped at 3, no floor -> continuous ordering
    n_big = np.minimum(post / (big + 1e-9), 3.0)
    return -(n_big / 3.0) - 0.05 * (post / (float(np.max(post)) + 1e-9))

