import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative huge-job occupancy: -g*occ, g = log-size gate of the arriving job, occ = sigmoid((load-tau)/w) with tau=0.4*max(past)."""
    m = len(loads)
    if past_jobs.size < 8:
        return np.zeros(m)
    mx = float(np.max(past_jobs))
    q60 = float(np.percentile(past_jobs, 60))
    lo = np.log1p(max(q60, 1e-9))
    hi = np.log1p(max(mx, 1e-9))
    if hi - lo < 1e-6:
        return np.zeros(m)
    g = np.clip(((np.log1p(max(job, 1e-9)) - lo) / (hi - lo) - 0.55) / 0.35, 0.0, 1.0)
    if g <= 0:
        return np.zeros(m)
    tau = 0.4 * mx
    w = max(0.07 * tau, 1e-9)
    occ = 1.0 / (1.0 + np.exp(-np.clip((loads - tau) / w, -60.0, 60.0)))
    return -g * occ

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative of projected load plus a softmax-weighted future huge-job charge, normalised."""
    m = len(loads)
    if past_jobs.size < 10 or jobs_left <= 0:
        return np.zeros(m)
    mx = np.max(past_jobs)
    med = np.median(past_jobs)
    thr = max(0.5 * mx, 3.0 * med)
    mask = past_jobs >= thr
    if not np.any(mask):
        return np.zeros(m)
    huge_left = np.mean(mask) * jobs_left
    huge_avg = np.mean(past_jobs[mask])
    total = huge_left * huge_avg
    if total <= 0:
        return np.zeros(m)
    post = loads + job
    T = max(np.mean(loads) + job, 1.0)
    z = np.clip(-loads / T, -60, 0)
    p = np.exp(z)
    p = p / np.sum(p)
    spread = np.max(loads) - np.min(loads) + job
    C = min(0.8 * spread / (np.max(p) - np.min(p) + 1e-9), total)
    s = -(post + C * p)
    return s / (np.max(np.abs(s)) + 1e-9)
